1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>PRAXIS — Demo Presentation Template</title>
7	<style>
8	  /* ============================================================
9	     PRAXIS Demo Presentation TEMPLATE
10	     ------------------------------------------------------------
11	     HOW TO USE
12	     - Open in any browser. Present full-screen (F11 / browser
13	       presentation mode).
14	     - Navigate: → / Space / click = next, ← = previous,
15	       Home = first slide, "f" = toggle footer help.
16	     - Each slide is a <section class="slide">. Edit the text
17	       inside. Replace every [[ BRACKETED ]] placeholder.
18	     - The per-slide footer (speaker name / role / email) is set
19	       with data- attributes on each <section>. Change those.
20	     - Color palette is pulled from the PRAXIS Project Plan.
21	     ============================================================ */
22	  :root{
23	    --ink:#11151c; --muted:#5b6470; --faint:#8a929c;
24	    --h1:#1F4E79; --h2:#2E75B6; --h3:#5B9BD5;
25	    --accent:#c98a2e;      /* trigger / gate gold from architecture */
26	    --good:#4f7d5a; --eval:#b03832; --gate:#3c3a66;
27	    --bg:#0e1116; --slide-bg:#ffffff; --line:#d9dde3; --soft:#eef3f9;
28	  }
29	  *{box-sizing:border-box;}
30	  html,body{margin:0;height:100%;}
31	  body{
32	    background:var(--bg); color:var(--ink);
33	    font-family:"Segoe UI",Arial,"Helvetica Neue",sans-serif;
34	    -webkit-font-smoothing:antialiased;
35	  }
36	
37	  /* ---- Slide shell -------------------------------------------------- */
38	  .deck{height:100vh;width:100vw;overflow:hidden;position:relative;}
39	  .slide{
40	    position:absolute;inset:0;display:none;flex-direction:column;
41	    padding:64px 84px 96px;background:var(--slide-bg);
42	  }
43	  .slide.active{display:flex;animation:fade .35s ease;}
44	  @keyframes fade{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:none;}}
45	
46	  /* ---- Typography --------------------------------------------------- */
47	  .kicker{font-size:.8rem;letter-spacing:.22em;text-transform:uppercase;
48	    color:var(--accent);font-weight:700;margin-bottom:18px;}
49	  h1.title{font-size:5.5rem;line-height:1;color:var(--h1);margin:0;font-weight:800;letter-spacing:-.02em;}
50	  h2.slidehead{font-size:2.5rem;line-height:1.1;color:var(--h2);margin:0 0 6px;font-weight:800;}
51	  .sub{font-size:1.35rem;color:var(--muted);margin:14px 0 0;line-height:1.4;max-width:60ch;}
52	  .body{font-size:1.25rem;line-height:1.55;color:var(--ink);max-width:62ch;}
53	  .body ul{padding-left:1.3em;margin:.4em 0;}
54	  .body li{margin:.5em 0;}
55	  .ph{color:#9aa3ad;font-style:italic;}     /* placeholder hint text */
56	  .hl{color:var(--h1);font-weight:700;}
57	  code{background:var(--soft);padding:1px 7px;border-radius:5px;font-size:.92em;color:var(--gate);}
58	
59	  .grow{flex:1 1 auto;display:flex;flex-direction:column;justify-content:center;}
60	
61	  /* ---- Title slide -------------------------------------------------- */
62	  .center{align-items:flex-start;justify-content:center;}
63	  .tagline{font-size:1.75rem;color:var(--ink);font-weight:600;margin:22px 0 0;max-width:48ch;line-height:1.3;}
64	  .repo{margin-top:34px;font-size:1.05rem;color:var(--muted);}
65	  .repo a{color:var(--h2);text-decoration:none;border-bottom:1px solid var(--line);}
66	  .badge{display:inline-block;font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;
67	    font-weight:700;color:#1f6f43;border:1.5px solid #1f6f43;border-radius:4px;
68	    padding:4px 10px;margin-left:10px;vertical-align:middle;}
69	
70	  /* ---- Team grid ---------------------------------------------------- */
71	  .team{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:8px;}
72	  .member{border:1px solid var(--line);border-radius:12px;padding:24px 22px;background:#fafcff;
73	    border-top:6px solid var(--h2);}
74	  .member:nth-child(1){border-top-color:var(--h1);}
75	  .member:nth-child(3){border-top-color:var(--h3);}
76	  .member .name{font-size:1.5rem;font-weight:800;color:var(--h1);}
77	  .member .pillar{font-size:1.05rem;font-weight:700;color:var(--h2);margin:6px 0 12px;}
78	  .member .desc{font-size:1rem;color:var(--muted);line-height:1.45;}
79	  .member .mail{display:block;margin-top:14px;font-size:.95rem;color:var(--faint);}
80	
81	  /* ---- Two-column content ------------------------------------------ */
82	  .cols{display:grid;grid-template-columns:1.1fr .9fr;gap:48px;align-items:start;}
83	  .panel{background:var(--soft);border-radius:12px;padding:26px 28px;font-size:1.1rem;line-height:1.5;}
84	  .panel h3{margin:0 0 10px;color:var(--gate);font-size:1.15rem;}
85	  .screenshot-frame{padding:10px;background:#f8fafc;border:1px solid var(--line);border-radius:10px;}
86	  .screenshot-frame img{display:block;width:100%;height:auto;border-radius:6px;border:1px solid #d8dee8;}
87	  .screenshot-caption{margin:8px 2px 0;color:var(--muted);font-size:.86rem;line-height:1.35;}
88	  .demo-strip{display:grid;grid-template-columns:1fr;gap:12px;}
89	  .demo-strip .screenshot-frame{padding:8px;}
90	  .demo-strip .screenshot-frame img{height:170px;object-fit:cover;object-position:top;}
91	  .demo-strip .screenshot-caption{font-size:.8rem;}
92	  .flow{font-size:1.05rem;color:var(--gate);font-weight:600;line-height:1.9;}
93	  .flow .arrow{color:var(--accent);font-weight:800;padding:0 6px;}
94	  .metric{font-size:3.2rem;font-weight:800;color:var(--eval);line-height:1;}
95	  .metric small{display:block;font-size:1rem;font-weight:600;color:var(--muted);margin-top:8px;}
96	  .metrics{display:flex;gap:46px;margin-top:10px;}
97	
98	  /* ---- Per-slide footer (speaker attribution) ---------------------- */
99	  .foot{position:absolute;left:84px;right:84px;bottom:30px;display:flex;
100	    justify-content:space-between;align-items:center;
101	    border-top:1px solid var(--line);padding-top:12px;font-size:.92rem;color:var(--muted);}
102	  .foot .who b{color:var(--h1);}
103	  .foot .role{color:var(--muted);}
104	  .foot .mail{color:var(--faint);}
105	  .foot .brand{font-weight:800;letter-spacing:.08em;color:var(--h2);}
106	
107	  /* ---- HUD: counter + progress ------------------------------------- */
108	  .hud{position:fixed;top:18px;right:24px;z-index:50;font-size:.85rem;color:#aeb6c0;
109	    background:rgba(255,255,255,.06);padding:5px 12px;border-radius:20px;backdrop-filter:blur(4px);}
110	  .progress{position:fixed;left:0;top:0;height:4px;background:var(--accent);z-index:50;transition:width .3s;}
111	  .help{position:fixed;bottom:14px;left:50%;transform:translateX(-50%);z-index:50;
112	    font-size:.78rem;color:#7c8590;background:rgba(255,255,255,.05);padding:5px 14px;border-radius:16px;}
113	  .help.hidden{display:none;}
114	
115	  @media (max-width:900px){
116	    .slide{padding:40px 32px 88px;}
117	    h1.title{font-size:3.2rem;} h2.slidehead{font-size:1.8rem;}
118	    .team{grid-template-columns:1fr;} .cols{grid-template-columns:1fr;gap:22px;}
119	    .foot{left:32px;right:32px;flex-wrap:wrap;gap:6px;}
120	  }
121	</style>
122	</head>
