379	<script>
380	  const slides = Array.from(document.querySelectorAll('.slide'));
381	  const hud = document.getElementById('hud');
382	  const progress = document.getElementById('progress');
383	  const help = document.getElementById('help');
384	  let i = 0;
385	
386	  function injectFooter(s){
387	    if (s.querySelector('.foot')) return;
388	    const f = document.createElement('div');
389	    f.className = 'foot';
390	    const contact = s.dataset.github || s.dataset.mail || '';
391	    f.innerHTML =
392	      '<span class="who"><b>'+ s.dataset.name +'</b> &nbsp;·&nbsp; '+
393	      '<span class="role">'+ s.dataset.role +'</span> &nbsp;·&nbsp; '+
394	      '<span class="mail">'+ contact +'</span></span>'+
395	      '<span class="brand">PRAXIS</span>';
396	    s.appendChild(f);
397	  }
398	  slides.forEach(injectFooter);
399	
400	  function show(n){
401	    i = Math.max(0, Math.min(slides.length-1, n));
402	    slides.forEach((s,k)=>s.classList.toggle('active', k===i));
403	    hud.textContent = (i+1)+' / '+slides.length;
404	    progress.style.width = ((i+1)/slides.length*100)+'%';
405	  }
406	  function next(){ show(i+1); }
407	  function prev(){ show(i-1); }
408	
409	  document.addEventListener('keydown', e=>{
410	    if(e.key==='ArrowRight'||e.key===' '||e.key==='PageDown'){ e.preventDefault(); next(); }
411	    else if(e.key==='ArrowLeft'||e.key==='PageUp'){ e.preventDefault(); prev(); }
412	    else if(e.key==='Home'){ show(0); }
413	    else if(e.key==='End'){ show(slides.length-1); }
414	    else if(e.key.toLowerCase()==='f'){ help.classList.toggle('hidden'); }
415	  });
416	  document.getElementById('deck').addEventListener('click', e=>{
417	    if(e.target.closest('a')) return;        /* let links work */
418	    next();
419	  });
420	  show(0);
421	  setTimeout(()=>help.classList.add('hidden'), 4500);
422	</script>
